{
  "PROP-6a4369e9-inv-043": {
    "property_id": "PROP-6a4369e9-inv-043",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-043",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/rpc_data_column_sidecars_by_range.go::streamDataColumnBatch::L164-165",
      "proof_trace": "The quota check exits immediately when quota reaches zero, breaking out of the sidecar loop mid-block. This violates atomicity: if Block B has sidecars [1,2,3] and quota=2, only sidecars 1 and 2 are sent, leaving sidecar 3 unsent despite sidecar 1 being included in the response.",
      "attack_scenario": "Attacker requests a large range forcing quota exhaustion mid-block. Peer receives partial sidecars for the final block, causing reconstruction failure or wasted bandwidth as the incomplete set is below the PeerDAS threshold required for data availability.",
      "checklist_id": "PROP-6a4369e9-inv-043"
    },
    "text": "All sidecars of a block must be included in by_range response if any sidecar is included.",
    "assertion": "forall block, resp: any_sidecar_included(block, resp) => all_sidecars_included(block, resp)",
    "covers": "SG-008",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

